public class CustomerEnquiry { private int enquiryId,customerId,businessId; private String message,status; public int getEnquiryId(){return enquiryId;} public void setEnquiryId(int v){enquiryId=v;} public int getCustomerId(){return customerId;} public void setCustomerId(int v){customerId=v;} public int getBusinessId(){return businessId;} public void setBusinessId(int v){businessId=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
